namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1,
            Title = "Classic Margherita Pizza",
            Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            AverageRating = 4.5,
            RatingCount = 12
        },
        new()
        {
            Id = 2,
            Title = "Chicken Tikka Masala",
            Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onions, garlic, and ginger.", "Add tomato puree and spices, simmer 15 minutes.", "Stir in cream and add chicken.", "Serve with basmati rice or naan."],
            AverageRating = 4.8,
            RatingCount = 24
        },
        new()
        {
            Id = 3,
            Title = "Beef Tacos",
            Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan.", "Fill tortillas with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            AverageRating = 4.2,
            RatingCount = 8
        },
        new()
        {
            Id = 4,
            Title = "Pasta Carbonara",
            Category = "Italian",
            Description = "Classic Roman pasta with eggs, cheese, pancetta, and black pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra cheese and pepper."],
            AverageRating = 4.6,
            RatingCount = 18
        },
        new()
        {
            Id = 5,
            Title = "Pad Thai",
            Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
            Steps = ["Soak rice noodles in warm water for 30 minutes.", "Mix fish sauce, tamarind paste, and sugar for the sauce.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add noodles and sauce, toss until coated.", "Add shrimp, bean sprouts, and peanuts. Serve with lime."],
            AverageRating = 4.4,
            RatingCount = 15
        },
        new()
        {
            Id = 6,
            Title = "Guacamole",
            Category = "Mexican",
            Description = "Fresh and creamy avocado dip with lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Halve avocados and remove pits.", "Mash avocado to desired consistency.", "Stir in lime juice, diced onion, jalapeño, and tomato.", "Add chopped cilantro and salt to taste.", "Serve immediately with tortilla chips."],
            AverageRating = 4.7,
            RatingCount = 20
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count + 10; // include seed ratings
        recipe.AverageRating = Math.Round(
            (_ratings[recipeId].Sum() + recipe.AverageRating * 10) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead">Discover and share delicious recipes from around the world.</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var category in RecipeService.GetCategories())
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                        <p class="card-text text-muted">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                        <a href="/category/@category" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++)
                                    {
                                        <text>★</text>
                                    }
                                </span>
                                <span class="text-muted small">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                            </div>
                        </div>
                        <div class="card-footer">
                            <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-3">@Recipe.Title</h1>
        <p class="lead">@Recipe.Description</p>

        <StarRating RecipeId="Recipe.Id" />

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header">
                        <h5 class="mb-0">🧾 Ingredients</h5>
                    </div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients)
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header">
                        <h5 class="mb-0">📋 Steps</h5>
                    </div>
                    <div class="card-body">
                        <ol class="mb-0">
                            @foreach (var step in Recipe.Steps)
                            {
                                <li class="mb-2">@step</li>
                            }
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
    <h6 class="mb-2">Rate this recipe:</h6>
    <div class="d-flex align-items-center gap-3">
        <div style="font-size: 1.5rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => Rate(star)"
                      @onmouseover="() => hoverRating = star"
                      @onmouseout="() => hoverRating = 0"
                      class="@(star <= DisplayRating ? "text-warning" : "text-muted")">
                    ★
                </span>
            }
        </div>
        @if (submitted)
        {
            <span class="badge bg-success">Thanks! You rated @userRating star(s).</span>
        }
    </div>
    <small class="text-muted">
        Community average: @GetAverageRating().ToString("F1") / 5
    </small>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int userRating;
    private int hoverRating;
    private bool submitted;

    private int DisplayRating => hoverRating > 0 ? hoverRating : userRating;

    private void Rate(int stars)
    {
        userRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }

    private double GetAverageRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        return recipe?.AverageRating ?? 0;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (isSubmitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Thank you for sharing "<strong>@submittedTitle</strong>" with the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
                <ValidationMessage For="() => model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="description" class="form-label">Short Description</label>
                <InputTextArea id="description" @bind-Value="model.Description" class="form-control" rows="2" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" @bind-Value="ingredientsText" class="form-control" rows="6"
                               placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="() => ingredientsText" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" @bind-Value="stepsText" class="form-control" rows="6"
                               placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
                <ValidationMessage For="() => stepsText" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeFormModel model = new();
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool isSubmitted;
    private string submittedTitle = string.Empty;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Description = model.Description ?? string.Empty,
            Ingredients = ingredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = stepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };

        RecipeService.SubmitRecipe(recipe);
        submittedTitle = recipe.Title;
        isSubmitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        public string? Description { get; set; }
    }
}

